#!/usr/bin/env bash
#
# apply_fixes.sh - Network Monitor: apply reviewed fixes, then build & test.
#
# Run from the repository root:  bash apply_fixes.sh
#
# It writes each changed/created file from an embedded (base64) copy, makes
# export.sh executable, then runs dotnet restore/build/test and prints a
# summary. File writing fails fast; build/test output is captured so the
# summary always prints. Exit code is non-zero if the build or tests fail.

set -euo pipefail

SCRIPT_DIR="$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)"
cd "$SCRIPT_DIR"

# Pick a base64 decode invocation that works on GNU (Linux, Git Bash) and BSD (macOS).
if printf "" | base64 --decode >/dev/null 2>&1; then
    B64D="base64 --decode"
else
    B64D="base64 -D"
fi

WRITTEN=0
write_file() {
    # $1 = repo-relative destination path; base64 content on stdin.
    local dest="$1"
    mkdir -p "$(dirname "$dest")"
    $B64D > "$dest"
    if [ ! -s "$dest" ]; then
        echo "ERROR: failed to write $dest" >&2
        exit 1
    fi
    WRITTEN=$((WRITTEN + 1))
    echo "  wrote $dest"
}

echo "Applying files..."

