__NM_B64__

chmod +x export.sh 2>/dev/null || true

echo ""
echo "Applied $WRITTEN file(s)."
echo ""

# ---- build & test (captured; must not abort the summary) --------------------
SLN="src/NetworkMonitor.slnx"
echo "Running: dotnet restore / build / test on $SLN"
echo ""
R_RESTORE=0; R_BUILD=-1; R_TEST=-1  # -1 = not run
set +e
dotnet restore "$SLN"
R_RESTORE=$?
if [ $R_RESTORE -eq 0 ]; then
    dotnet build "$SLN" --configuration Release --no-restore
    R_BUILD=$?
fi
if [ $R_BUILD -eq 0 ]; then
    dotnet test "$SLN" --configuration Release --no-build --verbosity normal
    R_TEST=$?
fi
set -e

# ---- summary ----------------------------------------------------------------
echo ""
echo "=============================================================="
echo "  Network Monitor - apply_fixes summary"
echo "=============================================================="
echo "Files applied:       $WRITTEN"
status() { if [ "$1" -eq -1 ]; then echo "skipped"; elif [ "$1" -eq 0 ]; then echo "OK"; else echo "FAILED ($1)"; fi; }
echo "dotnet restore:      $(status $R_RESTORE)"
echo "dotnet build:        $(status $R_BUILD)"
echo "dotnet test:         $(status $R_TEST)"
echo "--------------------------------------------------------------"
cat <<"SUMMARY"
What changed:
  Build/deps
    - src/Directory.Packages.props: SQLite CVE fix (SQLitePCLRaw.bundle_e_sqlite3
      3.x + SourceGear.sqlite3 3.53.3); latest stable OTel/xunit/test-sdk/extensions.
  Core fixes
    - PingService: resolve DNS once per round; IPv4-preferred address selection
      (IPv6 fallback only when enabled); cancellable ping; new Ping per call.
    - NetworkMonitorService/ComputeHealth: internet latency is the primary signal;
      a slow-but-reachable router no longer degrades health (it's annotated).
      Custom targets checked with bounded parallelism (MaxConcurrentChecks).
    - GatewayDetector / NetworkConfigurationService: smarter interface scoring and
      re-detection with cooldown.
    - MonitorBackgroundService: start-to-start cadence, skip+warn on overrun.
    - SqliteStorageService: persists EVERY target per cycle (not just router+internet);
      WAL + busy_timeout; adds target_name/packet_loss columns + sync_state table with
      an in-place migration.
    - ConsoleStatusDisplay: verbose mode prints all targets; local-time stamps; '--'
      for unmeasured targets.
  New optional feature
    - RemoteSync (libSQL/Turso): opt-in, fault-tolerant replication; never interrupts
      monitoring. Config under the RemoteSync section (empty by default = no-op).
  Tooling & docs
    - export.sh: git-aware file list, per-file SHA-256/size/lines, self-hash.
    - Workflows: action major-tag bumps (checkout@v7, setup-dotnet@v5,
      upload-artifact@v7, download-artifact@v8); stable .NET 10 channel; robust
      release notes; gh release --target; new dependency-check.yml; dependabot.yml.
    - README: remote sync, auto-detect, IPv6 policy, WAL/new columns, CVE note,
      corrected release matrix, roadmap.
SUMMARY
echo "=============================================================="

if [ $R_RESTORE -ne 0 ] || [ $R_BUILD -ne 0 ] || [ $R_TEST -ne 0 ]; then
    echo "One or more steps failed - see output above." >&2
    exit 1
fi
echo "All done: files applied, build and tests passed."

